#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* Roman numeral parser – reproduces the behaviour of prog29_roman_numeral_parser */

static const struct {
    const char *sym;
    int value;
} roman[] = {
    {"M",  1000},
    {"CM",  900},
    {"D",   500},
    {"CD",  400},
    {"C",   100},
    {"XC",   90},
    {"L",    50},
    {"XL",   40},
    {"X",    10},
    {"IX",    9},
    {"V",     5},
    {"IV",    4},
    {"I",     1}
};

/* return numeric value of a single Roman character, 0 if not a Roman symbol */
static int char_value(char c)
{
    switch (c) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
        default:  return 0;
    }
}

/* parse a Roman numeral that is already upper‑case and contains only legal symbols */
static int parse_roman(const char *s)
{
    int total = 0;
    size_t i = 0, len = strlen(s);
    while (i < len) {
        if (i + 1 < len) {
            if (s[i] == 'C' && s[i+1] == 'M') { total += 900; i += 2; continue; }
            if (s[i] == 'C' && s[i+1] == 'D') { total += 400; i += 2; continue; }
            if (s[i] == 'X' && s[i+1] == 'C') { total += 90;  i += 2; continue; }
            if (s[i] == 'X' && s[i+1] == 'L') { total += 40;  i += 2; continue; }
            if (s[i] == 'I' && s[i+1] == 'X') { total += 9;   i += 2; continue; }
            if (s[i] == 'I' && s[i+1] == 'V') { total += 4;   i += 2; continue; }
        }
        int v = char_value(s[i]);
        if (v == 0) return -1;   /* illegal character – should never happen after validation */
        total += v;
        ++i;
    }
    return total;
}

/* build the canonical Roman representation of a value 1..3999 */
static void build_canonical(int n, char *out)
{
    char *p = out;
    for (size_t i = 0; i < sizeof roman / sizeof roman[0]; ++i) {
        while (n >= roman[i].value) {
            strcpy(p, roman[i].sym);
            p += strlen(roman[i].sym);
            n -= roman[i].value;
        }
    }
    *p = '\0';
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        puts("INVALID");
        return 0;
    }

    const char *in = argv[1];
    size_t len = strlen(in);
    if (len == 0 || len > 63) {   // original binary limited length to 63
        puts("INVALID");
        return 0;
    }

    /* 1. Upper‑case copy and reject illegal characters */
    char buf[64];
    for (size_t i = 0; i < len; ++i) {
        char c = in[i];
        if ('a' <= c && c <= 'z')
            c = (char)toupper((unsigned char)c);
        if (char_value(c) == 0) {
            puts("INVALID");
            return 0;
        }
        buf[i] = c;
    }
    buf[len] = '\0';

    /* 2. Convert to integer */
    int value = parse_roman(buf);
    if (value <= 0 || value > 3999) {
        puts("INVALID");
        return 0;
    }

    /* 3. Build canonical form and compare */
    char canon[64];
    build_canonical(value, canon);
    if (strcmp(canon, buf) == 0) {
        printf("%d\n", value);
    } else {
        puts("INVALID");
    }
    return 0;
}
